protocol ICustomer { var name: String { get } }

final class CustomerCore: ICustomer {
    let name: String; init(name: String) { self.name = name }
    private var roles: [ObjectIdentifier: Any] = [:]           // core owns its roles
    func add<R: CustomerRole>(_ role: R) { roles[ObjectIdentifier(R.self)] = role }
    func role<R: CustomerRole>(_ type: R.Type) -> R? { roles[ObjectIdentifier(type)] as? R }
}

class CustomerRole { unowned let core: CustomerCore; init(core: CustomerCore) { self.core = core } }
final class BorrowerRole: CustomerRole { func borrow(_ n: Int) -> String { "\(core.name) borrows \(n)" } }
